namespace {
QString uuid(){return QUuid::createUuid().toString(QUuid::WithoutBraces);}
QJsonObject emptyPack(const QString &name){return {{"format","sj-sim-athlete-pack"},{"version",1},{"id",uuid()},{"name",name},{"profiles",QJsonArray()}};}
bool writeJson(const QString &file,const QJsonObject &object){QSaveFile output(file);const auto data=QJsonDocument(object).toJson(QJsonDocument::Indented);return output.open(QIODevice::WriteOnly) && output.write(data)==data.size() && output.commit();}
QString title(const QJsonObject &p){const QString name=(p["name"].toString()+" "+p["surname"].toString()).trimmed();return name.isEmpty()?QObject::tr("Nowy skoczek"):name;}
}
AthleteStudioController::AthleteStudioController(QObject *parent,const QString &root):QObject(parent),m_root(root.isEmpty()?QStandardPaths::writableLocation(QStandardPaths::AppDataLocation)+"/athlete-studio":root){
    for(const auto &entry:QDir(m_root).entryInfoList(QDir::Dirs|QDir::NoDotAndDotDot,QDir::Name)){
        QJsonObject pack;QString error;if(readPack(entry.absoluteFilePath()+"/pack.json",pack,error) && pack["id"].toString()==entry.fileName())m_packs.append(pack);
        else if(!error.isEmpty())m_message=tr("Nie wczytano paczki %1: %2").arg(entry.fileName(),error);
    }
    if(m_packs.isEmpty())m_packs.append(emptyPack(tr("Moi skoczkowie")));
    if(!currentPack()["profiles"].toArray().isEmpty())m_selected=0;
}
QString AthleteStudioController::directory(const QJsonObject &pack)const{return m_root+"/"+pack["id"].toString();}
QJsonObject AthleteStudioController::currentPack()const{return m_packs.value(m_pack);}
QString AthleteStudioController::packName()const{return currentPack()["name"].toString();}
void AthleteStudioController::status(const QString &message){m_message=message;emit changed();}
bool AthleteStudioController::persist(const QJsonObject &pack,QString &error)const{const auto path=directory(pack);if(!QDir().mkpath(path) || !writeJson(path+"/pack.json",pack)){error=tr("Nie udało się zapisać paczki. Zmiana nie została zastosowana.");return false;}return true;}
bool AthleteStudioController::commit(const QJsonObject &next,int selection,const QString &message){if(next==currentPack()){m_selected=selection;return true;}QString error;QSet<QString> ids;const auto profiles=next["profiles"].toArray();if(profiles.size()>10000){status(tr("Paczka może mieć najwyżej 10 000 profili."));return false;}for(const auto &entry:profiles){AthleteProfile checked;if(!AthleteProfile::fromJson(entry.toObject(),checked,error)){status(error);return false;}if(ids.contains(checked.id)){status(tr("Powtórzony identyfikator skoczka."));return false;}ids.insert(checked.id);}if(!persist(next,error)){status(error);return false;}m_undo.append(QJsonObject{{"pack",currentPack()},{"selection",m_selected}});if(m_undo.size()>100)m_undo.removeFirst();m_redo.clear();m_packs[m_pack]=next;m_selected=selection;m_message=message.isEmpty()?tr("Zapisano"):message;emit changed();return true;}
QVariantList AthleteStudioController::packs()const{QVariantList list;for(const auto &p:m_packs)list.append(QVariantMap{{"name",p["name"].toString()},{"count",p["profiles"].toArray().size()}});return list;}
QVariantList AthleteStudioController::profiles()const{QVariantList rows;const auto source=currentPack()["profiles"].toArray();for(int i=0;i<source.size();++i){auto p=source[i].toObject().toVariantMap();p["label"]=title(source[i].toObject());p["index"]=i;p["flag"]=QUrl::fromLocalFile(QDir("flags").absoluteFilePath(CountryCodes::toIso(p["country"].toString())+".svg")).toString();rows.append(p);}return rows;}
QVariantMap AthleteStudioController::profile()const{const auto entries=currentPack()["profiles"].toArray();if(m_selected<0 || m_selected>=entries.size())return {};const auto object=entries[m_selected].toObject();auto p=object.toVariantMap();p["label"]=title(object);p["flag"]=QUrl::fromLocalFile(QDir("flags").absoluteFilePath(CountryCodes::toIso(p["country"].toString())+".svg")).toString();const auto relative=object["portrait"].toString();p["photo"]=relative.isEmpty()?QString():QUrl::fromLocalFile(directory(currentPack())+"/"+relative).toString();return p;}
QVariantList AthleteStudioController::countries()const{QVariantList values;QSet<QString> codes;for(const auto &country:GlobalDatabase::get()->getCountries()){const auto code=CountryCodes::toFis(country.getAlpha3());if(code.size()!=3 || codes.contains(code))continue;codes.insert(code);values.append(QVariantMap{{"code",code},{"name",country.getName()+" · "+code},{"flag",QUrl::fromLocalFile(QDir("flags").absoluteFilePath(CountryCodes::toIso(code)+".svg")).toString()}});}return values;}
QVariantList AthleteStudioController::legacyPacks()const{QVariantList values;for(const auto &p:GlobalDatabase::get()->getPacks())if(p.kind==DataPack::Jumpers)values.append(QVariantMap{{"name",p.name},{"id",p.id},{"count",p.jumpers.size()}});return values;}
QVariantList AthleteStudioController::legacyAthletes(int pack)const{int index=0;for(const auto &p:GlobalDatabase::get()->getPacks())if(p.kind==DataPack::Jumpers){if(index++!=pack)continue;QVariantList values;for(int i=0;i<p.jumpers.size();++i)values.append(QVariantMap{{"name",p.jumpers[i].getNameAndSurname()},{"index",i}});return values;}return {};}
void AthleteStudioController::selectPack(int index){if(index<0 || index>=m_packs.size() || index==m_pack)return;m_pack=index;m_selected=currentPack()["profiles"].toArray().isEmpty()?-1:0;m_undo.clear();m_redo.clear();m_message.clear();emit changed();}
void AthleteStudioController::renamePack(const QString &name){if(name.trimmed().isEmpty() || name.size()>100){status(tr("Nazwa paczki musi mieć od 1 do 100 znaków."));return;}auto next=currentPack();next["name"]=name.trimmed();commit(next,m_selected);}
void AthleteStudioController::createPack(){auto next=emptyPack(tr("Nowa paczka %1").arg(m_packs.size()+1));QString error;if(!persist(next,error)){status(error);return;}m_packs.append(next);m_pack=m_packs.size()-1;m_selected=-1;m_undo.clear();m_redo.clear();m_message=tr("Utworzono paczkę");emit changed();}
void AthleteStudioController::select(int index){if(index<0 || index>=currentPack()["profiles"].toArray().size() || index==m_selected)return;m_selected=index;m_message.clear();emit changed();}
void AthleteStudioController::add(){auto next=currentPack();auto entries=next["profiles"].toArray();entries.append(AthleteProfile::create().toJson());next["profiles"]=entries;commit(next,entries.size()-1,tr("Dodano skoczka"));}
void AthleteStudioController::duplicate(){if(m_selected<0)return;auto next=currentPack();auto entries=next["profiles"].toArray();auto copy=entries[m_selected].toObject();copy["id"]=uuid();copy["surname"]=(copy["surname"].toString().left(90)+tr(" — kopia")).left(100);entries.append(copy);next["profiles"]=entries;commit(next,entries.size()-1,tr("Utworzono kopię"));}
void AthleteStudioController::remove(){if(m_selected<0)return;auto next=currentPack();auto entries=next["profiles"].toArray();entries.removeAt(m_selected);next["profiles"]=entries;commit(next,entries.isEmpty()?-1:qMin(m_selected,entries.size()-1),tr("Usunięto skoczka · możesz cofnąć"));}
void AthleteStudioController::setValue(const QString &key,const QVariant &value){if(m_selected<0)return;const QSet<QString> keys{"name","surname","country","overall","form","landing","birthYear","personalBest"};if(!keys.contains(key))return;auto next=currentPack();auto entries=next["profiles"].toArray();auto p=entries[m_selected].toObject();p[key]=QJsonValue::fromVariant(value);AthleteProfile checked;QString error;if(!AthleteProfile::fromJson(p,checked,error)){status(error);return;}entries[m_selected]=checked.toJson();next["profiles"]=entries;commit(next,m_selected);}
void AthleteStudioController::setPerk(int pair,int side,int level,bool toggle){if(m_selected<0 || pair<0 || pair>=3 || (side!=1 && side!=-1) || level<1 || level>2)return;auto next=currentPack();auto entries=next["profiles"].toArray();auto p=entries[m_selected].toObject();auto values=p["perks"].toArray();const int old=values[pair].toInt();values[pair]=(toggle && old*side>0)?0:side*level;p["perks"]=values;entries[m_selected]=p;next["profiles"]=entries;commit(next,m_selected);}
void AthleteStudioController::undo(){if(m_undo.isEmpty())return;const auto snapshot=m_undo.last();QString error;if(!persist(snapshot["pack"].toObject(),error)){status(error);return;}m_redo.append(QJsonObject{{"pack",currentPack()},{"selection",m_selected}});m_undo.removeLast();m_packs[m_pack]=snapshot["pack"].toObject();m_selected=snapshot["selection"].toInt();status(tr("Cofnięto"));}
void AthleteStudioController::redo(){if(m_redo.isEmpty())return;const auto snapshot=m_redo.last();QString error;if(!persist(snapshot["pack"].toObject(),error)){status(error);return;}m_undo.append(QJsonObject{{"pack",currentPack()},{"selection",m_selected}});m_redo.removeLast();m_packs[m_pack]=snapshot["pack"].toObject();m_selected=snapshot["selection"].toInt();status(tr("Ponowiono"));}
void AthleteStudioController::copyLegacy(int pack,int athlete){int index=0;for(const auto &p:GlobalDatabase::get()->getPacks())if(p.kind==DataPack::Jumpers){if(index++!=pack)continue;if(athlete<0 || athlete>=p.jumpers.size())return;const auto &old=p.jumpers[athlete];const auto skills=old.getJumperSkills();const double range=qMax(1,GlobalSimulationSettings::get()->getMaxSkills());auto profile=AthleteProfile::create();profile.name=old.getName();profile.surname=old.getSurname();profile.country=CountryCodes::toFis(old.getCountryCode());profile.birthYear=old.getBirthYear();profile.personalBest=qBound(0.,old.getPersonalBest(),500.);profile.overall=qBound(1,qRound((skills.getTakeoffTechnique()+skills.getFlightTechnique())*.5/range*100),100);profile.form=qBound(1,qRound(skills.getForm()/range*100),100);profile.landing=qBound(0,qRound(skills.getLandingStyle()/5.),4);profile.sourceId=old.getIDStr();auto next=currentPack();auto entries=next["profiles"].toArray();entries.append(profile.toJson());next["profiles"]=entries;if(commit(next,entries.size()-1,tr("Skopiowano. OVR i forma są przeliczone; lądowanie przybliżone. Perki dobierz od zera. Pozostałe stare parametry nie są przenoszone."))){const auto image=QDir("jumpersImages").absoluteFilePath(old.getImageName());if(!old.getImageName().isEmpty() && QFileInfo::exists(image)){const auto note=m_message;if(setPhoto(image))status(note);}}return;}}
bool AthleteStudioController::copyPortrait(const QString &file,QString &relative){QImageReader reader(file);reader.setAutoTransform(true);const auto size=reader.size();if(!size.isValid() || qint64(size.width())*size.height()>80000000){status(tr("Nieprawidłowe lub zbyt duże zdjęcie."));return false;}reader.setScaledSize(size.scaled(1600,1600,Qt::KeepAspectRatio));const auto image=reader.read();if(image.isNull()){status(tr("Nie udało się odczytać zdjęcia."));return false;}QByteArray bytes;QBuffer buffer(&bytes);buffer.open(QIODevice::WriteOnly);if(!image.save(&buffer,"PNG")){status(tr("Nie udało się przygotować zdjęcia."));return false;}relative="portraits/"+QString::fromLatin1(QCryptographicHash::hash(bytes,QCryptographicHash::Sha256).toHex())+".png";const auto folder=directory(currentPack());if(!QDir().mkpath(folder+"/portraits")){status(tr("Nie udało się utworzyć folderu zdjęć."));return false;}const auto path=folder+"/"+relative;if(QFileInfo::exists(path))return true;QSaveFile target(path);if(!target.open(QIODevice::WriteOnly) || target.write(bytes)!=bytes.size() || !target.commit()){status(tr("Nie udało się zapisać zdjęcia w paczce."));return false;}return true;}
bool AthleteStudioController::setPhoto(const QString &file){if(m_selected<0)return false;QString relative;if(!copyPortrait(file,relative))return false;auto next=currentPack();auto entries=next["profiles"].toArray();auto p=entries[m_selected].toObject();p["portrait"]=relative;entries[m_selected]=p;next["profiles"]=entries;return commit(next,m_selected);}
void AthleteStudioController::choosePhoto(){const auto file=QFileDialog::getOpenFileName(qobject_cast<QWidget *>(parent()),tr("Zdjęcie skoczka"),QDir("jumpersImages").absolutePath(),tr("Zdjęcia (*.png *.jpg *.jpeg *.webp)"));if(!file.isEmpty())setPhoto(file);}
void AthleteStudioController::clearPhoto(){if(m_selected<0)return;auto next=currentPack();auto entries=next["profiles"].toArray();auto p=entries[m_selected].toObject();p["portrait"]="";entries[m_selected]=p;next["profiles"]=entries;commit(next,m_selected);}
bool AthleteStudioController::readPack(const QString &file,QJsonObject &pack,QString &error)const{QFile input(file);if(!input.open(QIODevice::ReadOnly) || input.size()>20*1024*1024){error=tr("Nie można odczytać paczki (limit 20 MB). Zdjęcia są w osobnym folderze.");return false;}QJsonParseError parse;auto object=QJsonDocument::fromJson(input.readAll(),&parse).object();const auto id=object["id"].toString();if(parse.error!=QJsonParseError::NoError || object["format"]!="sj-sim-athlete-pack" || object["version"]!=1 || QUuid(id).isNull() || QUuid(id).toString(QUuid::WithoutBraces)!=id || object["name"].toString().trimmed().isEmpty() || object["name"].toString().size()>100 || !object["profiles"].isArray()){error=tr("Nieprawidłowy format nowej paczki skoczków.");return false;}QSet<QString> ids;const auto entries=object["profiles"].toArray();if(entries.size()>10000){error=tr("Paczka może mieć najwyżej 10 000 profili.");return false;}for(const auto &v:entries){AthleteProfile p;if(!v.isObject()){error=tr("Nieprawidłowy wpis skoczka w paczce.");return false;}if(!AthleteProfile::fromJson(v.toObject(),p,error))return false;if(ids.contains(p.id)){error=tr("Powtórzony identyfikator skoczka.");return false;}ids.insert(p.id);if(!p.portrait.isEmpty() && !QFileInfo::exists(QFileInfo(file).absolutePath()+"/"+p.portrait)){error=tr("Brakuje zdjęcia dołączonego do paczki.");return false;}}pack=object;return true;}
bool AthleteStudioController::exportTo(const QString &destination){if(QFileInfo::exists(destination)){status(tr("Wybierz nowy folder. Istniejące pliki nie zostaną nadpisane."));return false;}if(!QDir().mkpath(destination+"/portraits")){status(tr("Nie udało się utworzyć folderu eksportu."));return false;}bool success=true;QSet<QString> copied;for(const auto &v:currentPack()["profiles"].toArray()){const auto photo=v.toObject()["portrait"].toString();if(photo.isEmpty() || copied.contains(photo))continue;copied.insert(photo);if(!QFile::copy(directory(currentPack())+"/"+photo,destination+"/"+photo)){success=false;break;}}if(success)success=writeJson(destination+"/pack.json",currentPack());if(!success){QDir(destination).removeRecursively();status(tr("Nie udało się wyeksportować paczki."));return false;}status(tr("Wyeksportowano paczkę wraz ze zdjęciami"));return true;}
bool AthleteStudioController::importFrom(const QString &file){QJsonObject pack;QString error;if(!readPack(file,pack,error)){status(error);return false;}pack["id"]=uuid();const auto target=directory(pack);if(!QDir().mkpath(target+"/portraits")){status(tr("Nie udało się utworzyć folderu paczki."));return false;}QSet<QString> copied;for(const auto &v:pack["profiles"].toArray()){const auto photo=v.toObject()["portrait"].toString();if(photo.isEmpty() || copied.contains(photo))continue;copied.insert(photo);const auto source=QFileInfo(file).absolutePath()+"/"+photo;const auto base=QFileInfo(file).canonicalPath();if(!QFileInfo(source).canonicalFilePath().startsWith(base+"/") || !QFile::copy(source,target+"/"+photo)){QDir(target).removeRecursively();status(tr("Nie udało się skopiować zdjęć paczki."));return false;}}if(!persist(pack,error)){QDir(target).removeRecursively();status(error);return false;}m_packs.append(pack);m_pack=m_packs.size()-1;m_selected=pack["profiles"].toArray().isEmpty()?-1:0;m_undo.clear();m_redo.clear();status(tr("Wczytano kopię paczki"));return true;}
void AthleteStudioController::exportPack(){const auto parent=QFileDialog::getExistingDirectory(qobject_cast<QWidget *>(this->parent()),tr("Folder docelowy paczki"));if(!parent.isEmpty())exportTo(parent+"/sj-athletes-"+uuid().left(8));}
void AthleteStudioController::importPack(){const auto file=QFileDialog::getOpenFileName(qobject_cast<QWidget *>(parent()),tr("Wczytaj nową paczkę skoczków"),{},tr("Paczka skoczków (pack.json)"));if(!file.isEmpty())importFrom(file);}
